    /**
     * Returns the numeric value of the character in the given radix: its decimal digit value for a decimal digit (Nd),
     * 10 to 35 for a Latin letter (ASCII or fullwidth, either case), and -1 when the character is neither, the value
     * is not less than the radix, or the radix is outside {@link #MIN_RADIX} to {@link #MAX_RADIX}.
     *
     * @param ch the character to be converted
     * @param radix the radix
     * @return the numeric value represented by the character in the given radix, or -1
     */
    public static int digit(char ch, int radix) {
        return digit((int) ch, radix);
    }

    /**
     * Returns the numeric value of the code point in the given radix; see {@link #digit(char, int)}.
     *
     * @param codePoint the code point to be converted
     * @param radix the radix
     * @return the numeric value represented by the code point in the given radix, or -1
     */
    public static int digit(int codePoint, int radix) {
        if (radix < MIN_RADIX || radix > MAX_RADIX) {
            return -1;
        }
        int value = value(codePoint);
        return value < radix ? value : -1;
    }

    /**
     * Tells whether the character is a decimal digit: of Unicode category Nd, which is exactly the characters whose
     * {@link #digit} value in radix 10 is not -1.
     *
     * @param ch the character to be tested
     * @return true if the character is a digit
     */
    public static boolean isDigit(char ch) {
        return isDigit((int) ch);
    }

    /**
     * Tells whether the code point is a decimal digit; see {@link #isDigit(char)}.
     *
     * @param codePoint the code point to be tested
     * @return true if the code point is a digit
     */
    public static boolean isDigit(int codePoint) {
        int value = value(codePoint);
        return value >= 0 && value <= 9;
    }

    /**
     * Determines the character representation for a digit in the given radix: {@code '0'} to {@code '9'}, then
     * {@code 'a'} to {@code 'z'}; the null character when the digit is not valid in the radix or the radix is outside
     * {@link #MIN_RADIX} to {@link #MAX_RADIX}.
     *
     * @param digit the number to convert to a character
     * @param radix the radix
     * @return the char representation of the digit in the radix, or the null character
     */
    public static char forDigit(int digit, int radix) {
        if (digit >= radix || digit < 0) {
            return '\0';
        }
        if (radix < MIN_RADIX || radix > MAX_RADIX) {
            return '\0';
        }
        if (digit < 10) {
            return (char) ('0' + digit);
        }
        return (char) ('a' - 10 + digit);
    }

